use super::*;

/// Structure + classify every import statement in `code`. `provides` is the set of every record's
/// `provides` specifier (the record universe); an import whose `from` is in it is record-internal.
pub fn analyze_imports(code: &str, provides: &HashSet<String>) -> AnalyzedImports {
    let mut out = AnalyzedImports::default();
    for stmt in import_statements(code) {
        for spec in parse_statement(&stmt) {
            // `@/…` that is NOT a record `provides` is a floor FILE — not derivable, stays in code.
            if spec.from.starts_with("@/") && !provides.contains(&spec.from) {
                out.floor.push(spec);
            } else {
                out.derived.push(spec);
            }
        }
    }
    out
}
